pub fn find_component(slug: &str) -> Option<&'static CanonicalComponent> {
	CANONICAL_COMPONENTS.iter().find(|component| component.slug == slug)
}

pub fn family_by_id(id: CatalogueFamilyId) -> &'static CatalogueFamily {
	CATALOGUE_FAMILIES
		.iter()
		.find(|family| family.id == id)
		.expect("generated families cover every CatalogueFamilyId")
}

pub fn matches_search(component: &CanonicalComponent, query: &str) -> bool {
	let query = query.trim().to_ascii_lowercase();
	if query.is_empty() {
		return true;
	}
	let family = family_by_id(component.family);
	component.display_name.to_ascii_lowercase().contains(&query)
		|| component.description.to_ascii_lowercase().contains(&query)
		|| family.label.to_ascii_lowercase().contains(&query)
		|| component.kind.label().to_ascii_lowercase().contains(&query)
		|| component.collections.iter().any(|label| label.to_ascii_lowercase().contains(&query))
}

pub fn search_components(query: &str) -> Vec<&'static CanonicalComponent> {
	CANONICAL_COMPONENTS
		.iter()
		.filter(|component| matches_search(component, query))
		.collect()
}
